import{_ as r}from"./chunks/Audio.COine8Wh.js";import{_ as i}from"./chunks/Tags.BJ536pW3.js";import{c as n,o as l,j as a,G as t,ae as s,a as o}from"./chunks/framework.Bw0Gm4PQ.js";const m=JSON.parse('{"title":"Apex Area Technical Corrections Act","description":"","frontmatter":{"legisId":"2025-07-15-apex-area-technical-corrections-act","title":"Apex Area Technical Corrections Act","displayTitle":"Apex Area Technical Corrections Act","lawNumber":"119-24","billNumber":"H.R. 618","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ24.xml","publishDate":"2025-07-15T00:00:00-05:00","industries":["manufacturing","transportation","environment"],"agencies":[],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Apex Area Technical Corrections Act\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2025-07-15-apex-area-technical-corrections-act\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Apex Area Technical Corrections Act\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2025-07-15-apex-area-technical-corrections-act\\",\\"datePublished\\":\\"2025-07-15T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2025-07-15-apex-area-technical-corrections-act\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2025-07-15-apex-area-technical-corrections-act.md","filePath":"congress-bills/2025-07-15-apex-area-technical-corrections-act.md","lastUpdated":1788887623000}'),c={name:"congress-bills/2025-07-15-apex-area-technical-corrections-act.md"},f=Object.assign(c,{setup(d){return(p,e)=>(l(),n("div",null,[e[0]||(e[0]=a("h1",{id:"apex-area-technical-corrections-act",tabindex:"-1"},[o("Apex Area Technical Corrections Act "),a("a",{class:"header-anchor",href:"#apex-area-technical-corrections-act","aria-label":'Permalink to "Apex Area Technical Corrections Act"'},"​")],-1)),t(r),t(i,{list:"/congress-bills"}),e[1]||(e[1]=s('<p>Signed into law on Tuesday, July 15, 2025. Public Law 119-24, H.R. 618.</p><p><strong>Headline:</strong> Nevada’s Apex industrial area gets updated rules for land transfers, infrastructure, and mineral sales.</p><p><strong>Why it matters:</strong> The law expands local participation in developing the Apex Site while keeping future federal land actions subject to environmental and land-management laws.</p><p><strong>What the law does:</strong></p><ul><li>Lets the City of North Las Vegas and the Apex Industrial Park Owners Association join Clark County in infrastructure connections and certain land-related rights.</li><li>Applies the updated authority to the original Kerr-McGee Site and other lands transferred under the 1989 law.</li><li>Makes the federal land withdrawal permanent for all covered transferred lands.</li><li>Allows mineral materials created by grading or similar surface work to be sold without competition or ordinary noncompetitive-sale limits.</li><li>Requires additional federal land transfers, land interests, and rights-of-way to follow applicable federal land and environmental laws.</li></ul><p><strong>Who it affects:</strong></p><ul><li>The City of North Las Vegas, Clark County, and the Apex Industrial Park Owners Association.</li><li>Businesses, landowners, and infrastructure developers operating at the Apex Site.</li><li>Federal land managers overseeing transfers and rights-of-way in the area.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>People and businesses at the Apex Site may benefit from broader local coordination on infrastructure connections.</li><li>Future federal land actions at the site remain subject to applicable environmental and land-management safeguards.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="apex-area-technical-corrections-act-1" tabindex="-1">Apex Area Technical Corrections Act <a class="header-anchor" href="#apex-area-technical-corrections-act-1" aria-label="Permalink to &quot;Apex Area Technical Corrections Act&quot;">​</a></h3><p>This title updates the 1989 law governing federal land transfers and infrastructure at the Apex industrial area in Nevada. It formally includes the City of North Las Vegas and the Apex Industrial Park Owners Association, expands certain rights and procedures, and requires future federal land transfers and rights-of-way to comply with federal environmental and land-management laws.</p><p><strong>Key takeaways:</strong></p><ul><li>The City of North Las Vegas and the Apex Industrial Park Owners Association may participate with Clark County in infrastructure connections and certain land-related rights at the Apex Site.</li><li>The updated authority applies to the original Kerr-McGee Site and other lands transferred under the 1989 law, using the original or successor federal maps.</li><li>The federal land withdrawal continues permanently for all lands transferred under the relevant provision.</li><li>Mineral materials produced through grading, land balancing, or similar surface work may be sold without competition and without the usual limits on noncompetitive sales.</li><li>Additional federal land transfers, land interests, and rights-of-way at the Apex Site must comply with applicable federal land and environmental laws.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ24.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ24.xml</a></p>',15))]))}});export{m as __pageData,f as default};
